/**
 * The app shell, kept on the device (09 §4, D-078).
 *
 * **This is not a cache for speed.** Everything RPOS does offline — the menu,
 * the queue, the local bill, the arithmetic port — lives inside an application
 * that has to be downloaded from the server before any of it can run. Without
 * this file a till survives an outage exactly until somebody presses F5, and
 * then shows a white page with a customer standing at the counter.
 *
 * Written by hand rather than generated by Workbox. The whole of it is the
 * hundred lines below; a build plugin, a manifest format and a dependency tree
 * would be more moving parts than the problem has.
 *
 * `__PRECACHE__` and `d5fe6c0ecf1a` are filled in by `vite.config.ts`, which is the
 * only thing that knows the content-hashed filenames.
 *
 * Three rules it follows, and each one is load-bearing:
 *
 * 1. **`/api/` is never intercepted.** Those requests must fail *fast* when the
 *    line is down, because that failure is what puts the app into offline mode
 *    and what sends a write to the queue (`09` §2, §5). A service worker that
 *    helpfully served a stale API response would have the till acting on
 *    yesterday's answer.
 * 2. **The CSRF token is stripped before the shell is stored.** The page carries
 *    a per-session token, and Frappe caches www pages by path with no user in
 *    the key — the mistake `D-031` exists to prevent. Caching the page as it
 *    arrived would hand the next cashier the last one's token from *inside the
 *    browser*, where no `no_cache` header can reach. The app asks for a fresh
 *    one when it is online and has none (`api/client.ensureCsrfToken`), and
 *    offline it needs none: nothing is being sent.
 * 3. **Assets are cache-first, the shell is network-first.** Asset names carry
 *    a content hash, so a cached one can never be stale. The shell has no hash,
 *    so it is fetched when possible and served from the cache when not.
 */

const BUILD = "d5fe6c0ecf1a";
const CACHE = `rpos-shell-${BUILD}`;

/**
 * Everything the app needs to start, from the build that wrote this file.
 *
 * A real array with a placeholder inside it, not a bare `__PRECACHE__`, so this
 * file stays valid JavaScript and the linter keeps reading it. That is not
 * tidiness: it is how the missing `storeShell` below was caught before it
 * shipped.
 */
const PRECACHE = [
  "/assets/restaurant_pos/frontend/assets/AppIcon.vue_vue_type_script_setup_true_lang-D1sv4QUR.js",
  "/assets/restaurant_pos/frontend/assets/CustomerDisplayView-C5vNcp8P.js",
  "/assets/restaurant_pos/frontend/assets/DigitPad.vue_vue_type_script_setup_true_lang-B5492oNy.js",
  "/assets/restaurant_pos/frontend/assets/LocaleToggle.vue_vue_type_script_setup_true_lang-BYqa6XKH.js",
  "/assets/restaurant_pos/frontend/assets/OrderView-BvxrKQas.css",
  "/assets/restaurant_pos/frontend/assets/OrderView-DO1PfM9p.js",
  "/assets/restaurant_pos/frontend/assets/PaymentView-DW7vltXA.js",
  "/assets/restaurant_pos/frontend/assets/SelectProfileView-CaWXqazL.js",
  "/assets/restaurant_pos/frontend/assets/SignInView-CUYGB7mx.js",
  "/assets/restaurant_pos/frontend/assets/TableReadyDialog.vue_vue_type_script_setup_true_lang-Bl5XdYK8.js",
  "/assets/restaurant_pos/frontend/assets/TablesView-Bq9LdSVn.js",
  "/assets/restaurant_pos/frontend/assets/giftCard-BBe4Ej6-.js",
  "/assets/restaurant_pos/frontend/assets/index-BqGZ8WEX.js",
  "/assets/restaurant_pos/frontend/assets/index-Cb4HOye8.css",
  "/assets/restaurant_pos/frontend/assets/order-C1-3lmu0.js",
  "/assets/restaurant_pos/frontend/assets/order-CU1RNaRe.js",
  "/assets/restaurant_pos/frontend/assets/useCustomerDisplay-103aJR38.js",
  "/assets/restaurant_pos/frontend/assets/vendor-BPxTtZj4.js",
  "/assets/restaurant_pos/frontend/fonts/ibm-plex-mono-400-latin.woff2",
  "/assets/restaurant_pos/frontend/fonts/ibm-plex-mono-500-latin.woff2",
  "/assets/restaurant_pos/frontend/fonts/ibm-plex-sans-arabic-400-arabic.woff2",
  "/assets/restaurant_pos/frontend/fonts/ibm-plex-sans-arabic-400-latin.woff2",
  "/assets/restaurant_pos/frontend/fonts/ibm-plex-sans-arabic-500-arabic.woff2",
  "/assets/restaurant_pos/frontend/fonts/ibm-plex-sans-arabic-500-latin.woff2",
  "/assets/restaurant_pos/frontend/fonts/ibm-plex-sans-arabic-600-arabic.woff2",
  "/assets/restaurant_pos/frontend/fonts/ibm-plex-sans-arabic-600-latin.woff2",
  "/rpos-icon.svg",
  "/rpos-manifest.json"
];

/** Where Frappe serves this app's hashed files from. */
const ASSET_BASE = "/assets/restaurant_pos/frontend/";

/** The page the SPA is rendered by. */
const SHELL = "/restaurant-pos";

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);

      // One at a time, and failures are tolerated: a single asset that 404s
      // must not leave the terminal with no cache at all. Whatever did land is
      // still better than nothing.
      await Promise.allSettled(PRECACHE.map((url) => cache.add(url)));
      await storeShell(cache);

      // Take over without waiting for every tab to close. A cashier who
      // reloads once should have the protection immediately.
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      for (const name of await caches.keys()) {
        if (name.startsWith("rpos-shell-") && name !== CACHE) await caches.delete(name);
      }
      await self.clients.claim();
    })(),
  );
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Rule 1 — the API is the app's business, not this file's.
  if (url.pathname.startsWith("/api/")) return;

  if (request.mode === "navigate") {
    event.respondWith(shellFirstFromNetwork(request));
    return;
  }

  if (url.pathname.startsWith(ASSET_BASE)) {
    event.respondWith(cacheFirst(request));
  }
});

/**
 * Fetch the page and store it without its token.
 *
 * Done at install as well as on every navigation, because a terminal that is
 * installed and then loses the line before it navigates again would otherwise
 * have every asset cached and no page to hang them on.
 */
async function storeShell(cache) {
  try {
    const response = await fetch(SHELL, { credentials: "same-origin" });
    if (response.ok) await cache.put(SHELL, sanitise(await response.text(), response));
  } catch {
    // Installed while the line was already down. The assets that did land are
    // still worth keeping, and the next navigation stores the page.
  }
}

/** Network first: the shell has no content hash, so a fresh one is better. */
async function shellFirstFromNetwork(request) {
  try {
    const response = await fetch(request);
    if (response.ok) {
      const cache = await caches.open(CACHE);
      await cache.put(SHELL, sanitise(await response.clone().text(), response));
    }
    return response;
  } catch {
    const cached = await caches.match(SHELL);
    if (cached) return cached;

    // Nothing cached and no network. Better a sentence than a browser error
    // page: the cashier needs to know it is the connection, not the till.
    return new Response(OFFLINE_PAGE, {
      status: 503,
      headers: { "Content-Type": "text/html; charset=utf-8" },
    });
  }
}

/** Cache first: an asset filename carries its own content hash. */
async function cacheFirst(request) {
  const cached = await caches.match(request);
  if (cached) return cached;

  const response = await fetch(request);
  if (response.ok) {
    const cache = await caches.open(CACHE);
    await cache.put(request, response.clone());
  }
  return response;
}

/**
 * Rule 2 — take the session's token out before this page is stored.
 *
 * Matches the line `vite.config.ts` injects. If that line ever changes shape
 * this stops matching and the token would be cached, so the two are commented
 * as a pair.
 */
function sanitise(html, response) {
  const stripped = html.replace(
    /window\.csrf_token\s*=\s*"[^"]*"/,
    'window.csrf_token = ""',
  );

  return new Response(stripped, {
    status: response.status,
    statusText: response.statusText,
    headers: { "Content-Type": "text/html; charset=utf-8" },
  });
}

const OFFLINE_PAGE = `<!doctype html>
<html dir="rtl" lang="ar"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>RPOS</title></head>
<body style="font-family:system-ui;display:grid;place-items:center;height:100vh;margin:0;background:#f7f8fa;color:#1f2937">
<div style="text-align:center;padding:2rem">
<p style="font-size:1.25rem;font-weight:700;margin:0 0 .5rem">لا يوجد اتصال بالخادم</p>
<p style="margin:0;color:#6b7280">هذا الجهاز لم يحفظ نسخة من التطبيق بعد. أعد الاتصال مرة واحدة.</p>
</div></body></html>`;
